mapper.select:

WHERE M.use_yn='Y' AND L.USE_YN='Y'
  AND C.EMS_ID IN #{id}
  AND L.LINK_SYS_CD=#{linkSysCd}
  AND C.DATA_SE_CD=#{dataSeCd}
ORDER BY FIELD(C.EMS_ID,1,13,16,11,4),FIELD(C.DATA_SE_CD,'C','P','F','S')

mapper.update:
UPDATE com_ping_info SET PERF_CLCT_USE_YN=#{perfClctUseYn},PING_MNTR_USE_YN=#{pingMntrUseYn},
  CLCT_CYCLE_SEC=#{clctCycleSec},STTS_MNTR_CYCLE_SEC=#{sttsMntrCycleSec},
  TIMEOUT_SEC=#{timeoutSec},RTRY_NOCS=#{rtryNocs},TIMEOUT_POLL_SEC=#{timeoutPollSec},
  USE_YN=#{useYn},EXCN_TM=#{excnTm},CYCLE_CRTR_CN=#{cycleCrtrCn},
  MOD_DT=NOW(),MOD_ID=#{actorId}
WHERE EMS_ID=#{emsId} AND DATA_SE_CD=#{dataSeCd}
